// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/access/Ownable.sol";
import "./RoleBasedAccessControl.sol";

contract JudgeContract is Ownable {
    RoleBasedAccessControl public roleBasedAccessContract;
    address public admin;

    uint256 public constant INITIAL_SECURITY_TOKEN_BUDGET = 100;
    uint256 public constant PERMANENT_REVOCATION_THRESHOLD = 20;
    uint256 public constant SECURITY_PENALTY_UNAUTHORIZED = 15;
    uint256 public constant SECURITY_PENALTY_BLOCKED = 10;
    uint256 public constant SECURITY_PENALTY_DOS_ESCALATION = 30;
    uint256 public constant SECURITY_REWARD_BENIGN = 5;
    uint256 public constant RTK_REWARD_BENIGN = 1000;
    uint256 public constant BLOCKED_ATTEMPTS_FOR_DOS = 3;

    string public constant REASON_UNAUTHORIZED = "Unauthorized access attempt";
    string public constant REASON_BLOCKED_REPEAT = "Blocked repeated malicious attempt";
    string public constant REASON_QUARANTINE_REPEAT = "Repeated malicious attempt during quarantine";
    string public constant REASON_DOS = "Denial of Service";

    struct MisbehaviorRecord {
        string[] reasons;
        uint256 lastPenaltyTime;
        uint256 blockingEndTime;
    }

    struct Penalty {
        string level;
        mapping(RoleToken.Role => uint256) tokenDeduction;
        uint256 blockingDuration;
    }

    struct OffenseState {
        uint256 waveIndex;
        uint256 consecutiveMaliciousCount;
        uint256 blockedAttemptCount;
        uint256 quarantineLevel;
        uint256 quarantineUntil;
        bool permanentRevoked;
        uint256 lastMaliciousAt;
        uint256 lastBenignAt;
        uint256 securityTokenBudget;
        uint256 cumulativePenalty;
        uint256 lastRecoveryWave;
        uint256 escalationAppliedWave;
    }

    mapping(address => MisbehaviorRecord) public misbehaviorHistory;
    mapping(address => OffenseState) private offenseStates;
    mapping(address => bool) private offenseStateInitialized;
    mapping(string => Penalty) private penalties;

    uint256 public benignThreshold = 1 minutes;
    uint256 public benignThresholdForMalicious = 1 minutes;
    uint256 public misbehaviorThreshold = 1 minutes;

    event StatusUpdated(address indexed memberAddress, string newStatus);
    event Penalized(address indexed memberAddress, uint256 penaltyAmount, string reason);
    event MemberBlocked(address indexed memberAddress, uint256 blockingEndTime, string reason);
    event RewardIssued(address indexed memberAddress, uint256 rewardAmount);
    event OffenseRecorded(
        address indexed memberAddress,
        uint256 waveIndex,
        uint256 consecutiveMaliciousCount,
        uint256 blockedAttemptCount,
        string reason,
        uint256 rtkPenalty,
        uint256 securityPenalty,
        uint256 securityTokenBudget,
        uint256 cumulativePenalty
    );
    event QuarantineStartedOrUpdated(
        address indexed memberAddress,
        uint256 waveIndex,
        uint256 quarantineLevel,
        uint256 quarantineUntil,
        uint256 duration,
        string reason
    );
    event BenignRecoveryApplied(
        address indexed memberAddress,
        uint256 rewardAmount,
        uint256 securityReward,
        uint256 securityTokenBudget,
        uint256 lastBenignAt
    );
    event PermanentRevocationTriggered(
        address indexed memberAddress,
        uint256 waveIndex,
        uint256 securityTokenBudget,
        uint256 cumulativePenalty,
        string reason
    );

    constructor(address initialAdmin, address _roleBasedAccessContract) Ownable(initialAdmin) {
        admin = initialAdmin;
        roleBasedAccessContract = RoleBasedAccessControl(_roleBasedAccessContract);

        createPenalty(REASON_UNAUTHORIZED, "major", [9000, 7000, 5000], 0);
        createPenalty("Too frequent access", "minor", [5000, 3000, 1000], 0);
        createPenalty("Data leakage attempt", "major", [11000, 9000, 7000], 0);
        createPenalty("Privilege escalation", "major", [14000, 12000, 10000], 0);
        createPenalty("Spoofing attempt", "minor", [6000, 4000, 2000], 0);
        createPenalty("Repudiation attempt", "minor", [7000, 5000, 3000], 0);
        createPenalty("Tampering with data", "major", [12000, 10000, 8000], 0);
        createPenalty(REASON_DOS, "major", [24000, 22000, 20000], 0);
        createPenalty(REASON_BLOCKED_REPEAT, "major", [9000, 7000, 5000], 0);
        createPenalty(REASON_QUARANTINE_REPEAT, "major", [9000, 7000, 5000], 0);
    }

    modifier onlyAdmin() {
        require(roleBasedAccessContract.getRole(msg.sender) == RoleToken.Role.ADMIN, "Access denied: Not an Admin");
        _;
    }

    function createPenalty(
        string memory reason,
        string memory level,
        uint16[3] memory deductions,
        uint256 duration
    ) internal {
        Penalty storage penalty = penalties[reason];
        penalty.level = level;
        penalty.blockingDuration = duration;
        penalty.tokenDeduction[RoleToken.Role.PRIMARY_GROUP_HEAD] = deductions[0];
        penalty.tokenDeduction[RoleToken.Role.SECONDARY_GROUP_HEAD] = deductions[1];
        penalty.tokenDeduction[RoleToken.Role.REGULAR_MEMBER] = deductions[2];
    }

    function reportMaliciousActivity(address _memberAddress, string memory reason) external onlyAdmin
        returns (uint256 penaltyAmount, string memory reasonString, uint256 blockingEndTime) {
        require(bytes(reason).length > 0, "Reason cannot be empty");

        OffenseState storage state = _ensureOffenseState(_memberAddress);
        MisbehaviorRecord storage record = misbehaviorHistory[_memberAddress];
        uint256 currentTime = block.timestamp;

        if (state.permanentRevoked) {
            record.reasons.push(reason);
            record.lastPenaltyTime = currentTime;
            state.lastMaliciousAt = currentTime;
            _emitOffenseRecorded(_memberAddress, state, "Permanent revocation", 0, 0);
            return (0, "Permanent revocation", record.blockingEndTime);
        }

        _maybeStartNextWave(state);

        string memory effectiveReason = reason;
        if (isTemporarilyQuarantined(_memberAddress) && !_isBlockedReason(reason)) {
            effectiveReason = REASON_QUARANTINE_REPEAT;
        }

        Penalty storage penalty = penalties[effectiveReason];
        if (bytes(penalty.level).length == 0) {
            penalty = penalties[REASON_UNAUTHORIZED];
        }

        record.reasons.push(effectiveReason);
        record.lastPenaltyTime = currentTime;

        state.consecutiveMaliciousCount += 1;
        state.lastMaliciousAt = currentTime;

        updateMemberStatus(_memberAddress, penalty.level);

        RoleToken.Role memberRole = roleBasedAccessContract.getRole(_memberAddress);
        uint256 rtkPenalty = penalty.tokenDeduction[memberRole];
        uint256 securityPenalty = _securityPenaltyForReason(effectiveReason);

        if (_isBlockedReason(effectiveReason)) {
            state.blockedAttemptCount += 1;
        }

        _penalizeMember(_memberAddress, rtkPenalty, effectiveReason, state);
        _deductSecurityBudget(state, securityPenalty);

        if (
            state.blockedAttemptCount >= BLOCKED_ATTEMPTS_FOR_DOS &&
            state.escalationAppliedWave < state.waveIndex
        ) {
            uint256 baseUnauthorizedPenalty = penalties[REASON_UNAUTHORIZED].tokenDeduction[memberRole];
            uint256 extraRtkPenalty = baseUnauthorizedPenalty * 3;
            state.escalationAppliedWave = state.waveIndex;
            _penalizeMember(_memberAddress, extraRtkPenalty, REASON_DOS, state);
            _deductSecurityBudget(state, SECURITY_PENALTY_DOS_ESCALATION);
            _startOrUpdateQuarantine(_memberAddress, state, effectiveReason);
        }

        _maybeTriggerPermanentRevocation(_memberAddress, state, effectiveReason);

        _emitOffenseRecorded(_memberAddress, state, effectiveReason, rtkPenalty, securityPenalty);

        return (rtkPenalty, effectiveReason, record.blockingEndTime);
    }

    function reportNonPenalizeMisbehavior(address _memberAddress) external onlyAdmin returns (uint256 rewardAmount, string memory newStatus) {
        OffenseState storage state = _ensureOffenseState(_memberAddress);

        if (state.permanentRevoked) {
            return (0, "PERMANENTLY_REVOKED");
        }

        RoleToken.Member memory member = roleBasedAccessContract.getMember(_memberAddress);
        uint256 currentTime = block.timestamp;
        uint256 timeSinceStatusUpdate = currentTime - member.lastStatusUpdate;
        bool hasRecoveredFromMaliciousWindow = state.lastMaliciousAt > 0 &&
            currentTime >= state.lastMaliciousAt + benignThresholdForMalicious &&
            state.lastRecoveryWave < state.waveIndex;
        bool hasBenignThresholdElapsed = state.lastMaliciousAt == 0 &&
            keccak256(abi.encodePacked(member.status)) == keccak256(abi.encodePacked("BENIGN")) &&
            timeSinceStatusUpdate >= benignThreshold;

        if (hasRecoveredFromMaliciousWindow || hasBenignThresholdElapsed) {
            rewardMember(_memberAddress);
            _rewardSecurityBudget(state);
            state.lastBenignAt = currentTime;
            state.lastRecoveryWave = state.waveIndex;
            state.consecutiveMaliciousCount = 0;
            state.blockedAttemptCount = 0;

            if (state.quarantineUntil <= currentTime) {
                state.quarantineUntil = 0;
                misbehaviorHistory[_memberAddress].blockingEndTime = 0;
            }

            updateMemberStatus(_memberAddress, "nothing");
            emit BenignRecoveryApplied(
                _memberAddress,
                RTK_REWARD_BENIGN,
                SECURITY_REWARD_BENIGN,
                state.securityTokenBudget,
                currentTime
            );
            return (RTK_REWARD_BENIGN, "BENIGN");
        }

        if (
            keccak256(abi.encodePacked(member.status)) == keccak256(abi.encodePacked("SUSPICIOUS")) &&
            timeSinceStatusUpdate >= benignThreshold
        ) {
            updateMemberStatus(_memberAddress, "nothing");
            state.lastBenignAt = currentTime;
            return (0, "BENIGN");
        }

        return (0, "not changed");
    }

    function _ensureOffenseState(address _memberAddress) internal returns (OffenseState storage) {
        OffenseState storage state = offenseStates[_memberAddress];
        if (!offenseStateInitialized[_memberAddress]) {
            state.securityTokenBudget = INITIAL_SECURITY_TOKEN_BUDGET;
            offenseStateInitialized[_memberAddress] = true;
        }
        return state;
    }

    function _maybeStartNextWave(OffenseState storage state) internal {
        if (state.waveIndex == 0 || state.lastRecoveryWave == state.waveIndex) {
            state.waveIndex += 1;
            state.consecutiveMaliciousCount = 0;
            state.blockedAttemptCount = 0;
            state.quarantineLevel = 0;
            state.quarantineUntil = 0;
            state.escalationAppliedWave = 0;
        }
    }

    function _securityPenaltyForReason(string memory reason) internal pure returns (uint256) {
        if (_isBlockedReason(reason)) {
            return SECURITY_PENALTY_BLOCKED;
        }
        return SECURITY_PENALTY_UNAUTHORIZED;
    }

    function _isBlockedReason(string memory reason) internal pure returns (bool) {
        bytes32 reasonHash = keccak256(abi.encodePacked(reason));
        return reasonHash == keccak256(abi.encodePacked(REASON_BLOCKED_REPEAT)) ||
            reasonHash == keccak256(abi.encodePacked(REASON_QUARANTINE_REPEAT)) ||
            reasonHash == keccak256(abi.encodePacked(REASON_DOS));
    }

    function _deductSecurityBudget(OffenseState storage state, uint256 amount) internal {
        if (amount == 0) {
            return;
        }
        if (amount >= state.securityTokenBudget) {
            state.securityTokenBudget = 0;
        } else {
            state.securityTokenBudget -= amount;
        }
    }

    function _rewardSecurityBudget(OffenseState storage state) internal {
        uint256 updatedBudget = state.securityTokenBudget + SECURITY_REWARD_BENIGN;
        state.securityTokenBudget = updatedBudget > INITIAL_SECURITY_TOKEN_BUDGET
            ? INITIAL_SECURITY_TOKEN_BUDGET
            : updatedBudget;
    }

    function _penalizeMember(
        address _memberAddress,
        uint256 penaltyAmount,
        string memory reason,
        OffenseState storage state
    ) internal {
        if (penaltyAmount > 0) {
            roleBasedAccessContract.penalizeMember(_memberAddress, penaltyAmount);
            state.cumulativePenalty += penaltyAmount;
        }
        emit Penalized(_memberAddress, penaltyAmount, reason);
    }

    function _emitOffenseRecorded(
        address _memberAddress,
        OffenseState storage state,
        string memory reason,
        uint256 rtkPenalty,
        uint256 securityPenalty
    ) internal {
        emit OffenseRecorded(
            _memberAddress,
            state.waveIndex,
            state.consecutiveMaliciousCount,
            state.blockedAttemptCount,
            reason,
            rtkPenalty,
            securityPenalty,
            state.securityTokenBudget,
            state.cumulativePenalty
        );
    }

    function rewardMember(address _memberAddress) internal {
        roleBasedAccessContract.rewardMember(_memberAddress, RTK_REWARD_BENIGN);
        emit RewardIssued(_memberAddress, RTK_REWARD_BENIGN);
    }

    function _startOrUpdateQuarantine(
        address _memberAddress,
        OffenseState storage state,
        string memory reason
    ) internal {
        uint256 duration = _quarantineDurationForWave(state.waveIndex);
        state.quarantineLevel = state.waveIndex;
        state.quarantineUntil = block.timestamp + duration;

        MisbehaviorRecord storage record = misbehaviorHistory[_memberAddress];
        record.blockingEndTime = state.quarantineUntil;

        emit MemberBlocked(_memberAddress, state.quarantineUntil, reason);
        emit QuarantineStartedOrUpdated(
            _memberAddress,
            state.waveIndex,
            state.quarantineLevel,
            state.quarantineUntil,
            duration,
            reason
        );
    }

    function _quarantineDurationForWave(uint256 waveIndex) internal pure returns (uint256) {
        if (waveIndex == 0) {
            return 1 minutes;
        }
        if (waveIndex > 3) {
            return 3 minutes;
        }
        return waveIndex * 1 minutes;
    }

    function _maybeTriggerPermanentRevocation(
        address _memberAddress,
        OffenseState storage state,
        string memory reason
    ) internal {
        if (state.permanentRevoked) {
            return;
        }

        bool completedThirdWave = state.quarantineLevel >= 3;
        bool exhaustedBudgetAfterFinalWave = state.waveIndex >= 3 &&
            state.securityTokenBudget <= PERMANENT_REVOCATION_THRESHOLD;

        if (!completedThirdWave && !exhaustedBudgetAfterFinalWave) {
            return;
        }

        state.permanentRevoked = true;
        state.quarantineUntil = type(uint256).max;
        misbehaviorHistory[_memberAddress].blockingEndTime = type(uint256).max;

        updateMemberStatus(_memberAddress, "major");

        try roleBasedAccessContract.revokeRole(_memberAddress) {
        } catch {
        }

        emit PermanentRevocationTriggered(
            _memberAddress,
            state.waveIndex,
            state.securityTokenBudget,
            state.cumulativePenalty,
            reason
        );
    }

    function updateMemberStatus(address _memberAddress, string memory penaltyLevel) internal {
        if (keccak256(abi.encodePacked(penaltyLevel)) == keccak256(abi.encodePacked("major"))) {
            roleBasedAccessContract.updateMemberStatus(_memberAddress, "MALICIOUS");
            emit StatusUpdated(_memberAddress, "MALICIOUS");
        } else if (keccak256(abi.encodePacked(penaltyLevel)) == keccak256(abi.encodePacked("minor"))) {
            roleBasedAccessContract.updateMemberStatus(_memberAddress, "SUSPICIOUS");
            emit StatusUpdated(_memberAddress, "SUSPICIOUS");
        } else if (keccak256(abi.encodePacked(penaltyLevel)) == keccak256(abi.encodePacked("nothing"))) {
            roleBasedAccessContract.updateMemberStatus(_memberAddress, "BENIGN");
            emit StatusUpdated(_memberAddress, "BENIGN");
        }
    }

    function getBlockingEndTime(address _memberAddress) external view returns (uint256) {
        return misbehaviorHistory[_memberAddress].blockingEndTime;
    }

    function getSecurityTokenBudget(address _memberAddress) external view returns (uint256) {
        if (!offenseStateInitialized[_memberAddress]) {
            return INITIAL_SECURITY_TOKEN_BUDGET;
        }
        return offenseStates[_memberAddress].securityTokenBudget;
    }

    function getCumulativePenalty(address _memberAddress) external view returns (uint256) {
        return offenseStates[_memberAddress].cumulativePenalty;
    }

    function getWaveIndex(address _memberAddress) external view returns (uint256) {
        return offenseStates[_memberAddress].waveIndex;
    }

    function getBlockedAttemptCount(address _memberAddress) external view returns (uint256) {
        return offenseStates[_memberAddress].blockedAttemptCount;
    }

    function getQuarantineUntil(address _memberAddress) external view returns (uint256) {
        return offenseStates[_memberAddress].quarantineUntil;
    }

    function isPermanentlyRevoked(address _memberAddress) public view returns (bool) {
        return offenseStates[_memberAddress].permanentRevoked;
    }

    function getLastMaliciousAt(address _memberAddress) external view returns (uint256) {
        return offenseStates[_memberAddress].lastMaliciousAt;
    }

    function getLastBenignAt(address _memberAddress) external view returns (uint256) {
        return offenseStates[_memberAddress].lastBenignAt;
    }

    function isTemporarilyQuarantined(address _memberAddress) public view returns (bool) {
        OffenseState storage state = offenseStates[_memberAddress];
        return !state.permanentRevoked &&
            state.quarantineUntil != 0 &&
            block.timestamp < state.quarantineUntil;
    }

    function shouldRecordBlockedAttempt(address _memberAddress) external view returns (bool) {
        OffenseState storage state = offenseStates[_memberAddress];
        return !state.permanentRevoked &&
            state.waveIndex > 0 &&
            state.lastRecoveryWave < state.waveIndex;
    }

    function getOffenseState(address _memberAddress)
        external
        view
        returns (
            uint256 waveIndex,
            uint256 consecutiveMaliciousCount,
            uint256 blockedAttemptCount,
            uint256 quarantineLevel,
            uint256 quarantineUntil,
            bool permanentRevoked,
            uint256 lastMaliciousAt,
            uint256 lastBenignAt,
            uint256 securityTokenBudget,
            uint256 cumulativePenalty
        )
    {
        OffenseState storage state = offenseStates[_memberAddress];
        waveIndex = state.waveIndex;
        consecutiveMaliciousCount = state.consecutiveMaliciousCount;
        blockedAttemptCount = state.blockedAttemptCount;
        quarantineLevel = state.quarantineLevel;
        quarantineUntil = state.quarantineUntil;
        permanentRevoked = state.permanentRevoked;
        lastMaliciousAt = state.lastMaliciousAt;
        lastBenignAt = state.lastBenignAt;
        securityTokenBudget = offenseStateInitialized[_memberAddress]
            ? state.securityTokenBudget
            : INITIAL_SECURITY_TOKEN_BUDGET;
        cumulativePenalty = state.cumulativePenalty;
    }
}
